import './neon-chip-select-single.scss';
import { NeonWidget } from '../shared/neon-widget';
import { dynamicText, createElement, updateDynamicText, updateDynamicAttribute, updateConditionalElements, updateDynamicProperty, dynamicAttr, dynamicProperty, elementIsDisabled, createElementIf } from '../shared/dom-manipulation';
import { addTranslationListener } from '@ps-refarch-ux/mfe-utils';
import { stringHasCharacters } from '../shared/string-utils';
export class NeonChipSelectSingle extends NeonWidget {
    //Any attribute that should be watched for changes should be listed here.
    static get observedAttributes() {
        return [
            'id',
            'data-label-text',
            'name',
            'value',
            'data-show-label',
            'disabled',
            'data-tooltip-text',
            'data-tooltip-placement',
            'data-size',
            'data-unchecked-icon',
            'data-use-unchecked-icon'
        ];
    }
    set value(value) {
        const isIndeterminate = value === 'indeterminate';
        if (isIndeterminate && this.getAttribute('data-check-type') === 'toggle') {
            this.input.indeterminate = false;
            this.input.checked = false;
            console.error('The indeterminate state for data-check-type="toggle" is not supported');
        }
        this.input.indeterminate = isIndeterminate;
        this.input.checked = value === true;
    }
    get value() {
        return this.input.getValue();
    }
    // taken from abstract-input-field
    // perhaps this should be factored out into its own utility
    constructor() {
        super();
        this.widgetTag = 'neon-chip-select-single';
        this.isIdRequired = true;
        this.isDisabled = false;
        //The neon-tooltip removes its child nodes and stores them in memory.
        //Our dynamic system requires elements to be in the DOM to be updated so
        //instead of using that, we create a TextNode object and just keep it updated
        //with whatever is in the data-tooltip attribute.  This can be updated whether it's
        //in the DOM or not.
        this.tooltipTextNode = document.createTextNode('');
        this.isIdRequired = true;
        this.input = createElement('input', {
            attrs: {
                type: 'checkbox',
                id: dynamicAttr(() => {
                    if (this.getAttribute('id') != null) {
                        return 'chip-select-single-' + this.getAttribute('id');
                    }
                }),
                name: dynamicAttr(() => {
                    if (this.getAttribute('name') != null) {
                        return this.getAttribute('name');
                    }
                })
            },
            properties: {
                //getValue is a function not a dynamic property
                getValue: function () {
                    return this.indeterminate ? 'indeterminate' : this.checked;
                },
                checked: this.getAttribute('value') === 'true',
                indeterminate: this.getAttribute('value') === 'indeterminate',
                disabled: dynamicProperty(() => { return elementIsDisabled(this); })
            },
            listeners: {
                blur: (event) => {
                    //blur events don't bubble, so we need to make the neon-2_20_1-radio-single blast it out to whoever wants to listen to it.
                    this.dispatchEvent(new Event('blur'));
                }
            }
        });
    }
    validateInputs() {
        super.validateInputs();
        if (!stringHasCharacters(this.getAttribute('data-label-text'))) {
            console.error('data-label-text is required on all Neon checkboxes. If you would like to hide the text from sighted users, set data-show-label="false".');
        }
    }
    getSizeClass() {
        const size = this.getAttribute('data-size');
        switch (size) {
            case 'small':
                return ' input-size-small';
            case 'medium':
                return ' input-size-medium';
            case 'large':
                return ' input-size-large';
            case 'x-large':
                return ' input-size-x-large';
            case 'auto':
                return ' input-size-auto';
            default:
                return '';
        }
    }
    getColorWeight() {
        return elementIsDisabled(this) ? '200' : '100';
    }
    //when the attributes change this will run
    attributeChanged(attrName, oldVal, newVal) {
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        switch (attrName) {
            case 'id':
                updateDynamicAttribute(this, 'id');
                updateDynamicAttribute(this, 'for');
                break;
            case 'data-label-text':
                updateDynamicText(this);
                updateDynamicAttribute(this, 'data-label-text');
                break;
            case 'name':
                updateDynamicAttribute(this, 'name');
                break;
            case 'value':
                this.value = newVal === 'indeterminate' ? 'indeterminate' : (newVal === 'true');
                updateDynamicAttribute(this, 'class');
                break;
            case 'disabled':
                updateDynamicProperty(this, 'disabled');
                break;
            case 'data-size':
                updateDynamicAttribute(this, 'class');
                break;
            case 'data-show-label':
                updateDynamicAttribute(this, 'data-show-label');
                break;
            case 'data-tooltip-text':
                updateConditionalElements(this);
                this.tooltipTextNode.nodeValue = newVal;
                break;
            case 'data-tooltip-placement':
                updateDynamicAttribute(this, 'data-placement');
                break;
            case 'data-unchecked-icon':
                updateDynamicAttribute(this, 'data-icon');
                break;
            case 'data-use-unchecked-icon':
                updateConditionalElements(this);
                break;
            default:
        }
        updateConditionalElements(this);
    }
    getChipSelectSingleClasses() {
        const chipSelectSingleClasses = ['neon-chip-select-single-label'];
        if (this.input.checked) {
            chipSelectSingleClasses.push('neon-chip-select-single-selected');
        }
        else {
            chipSelectSingleClasses.push('neon-chip-select-single-unselected');
        }
        chipSelectSingleClasses.push(this.getSizeClass());
        return chipSelectSingleClasses.join(' ');
    }
    render() {
        return createElement('label', {
            attrs: {
                for: dynamicAttr(() => {
                    if (this.getAttribute('id') != null) {
                        return 'chip-select-single-' + this.getAttribute('id');
                    }
                }),
                class: dynamicAttr(() => { return this.getChipSelectSingleClasses(); })
            }
        }, this.input, 
        //append icon
        createElementIf(() => {
            return this.input.checked;
        }, 'neon-2_20_1-icon', {
            attrs: {
                class: 'neon-chip-select-single-icon-checked',
                'data-icon': 'mark-check',
                'data-size': 'x-small',
                'data-size-mobile': 'small'
            }
        }), createElementIf(() => {
            return !this.input.checked && this.getAttribute('data-use-unchecked-icon') !== 'false';
        }, 'neon-2_20_1-icon', {
            attrs: {
                class: dynamicAttr(() => {
                    return stringHasCharacters(this.getAttribute('data-unchecked-icon')) ? 'neon-chip-select-single-icon-unchecked-custom' : 'neon-chip-select-single-icon-unchecked-circle';
                }),
                'data-icon': dynamicAttr(() => {
                    const uncheckedIcon = this.getAttribute('data-unchecked-icon');
                    return stringHasCharacters(uncheckedIcon) ? uncheckedIcon : 'status-inactive';
                }),
                'data-size': 'x-small',
                'data-size-mobile': 'small'
            }
        }), 
        //create a text span
        createElementIf(() => { return this.getAttribute('data-label-text') != null && this.getAttribute('data-show-label') !== 'false'; }, 'span', {
            attrs: {
                'data-label-text': dynamicAttr(() => {
                    return this.getAttribute('data-label-text');
                }),
                class: dynamicAttr(() => { return 'neon-chip-select-single-text' + (this.input.checked ? ' neon-chip-select-single-text-selected' : ''); })
            },
            text: dynamicText(() => { return this.getAttribute('data-label-text'); })
        }), createElementIf(() => { return this.getAttribute('data-tooltip-text') != null; }, 'neon-2_20_1-tooltip', {
            attrs: {
                'data-target-id': dynamicAttr(() => { return this.getAttribute('id'); }),
                'data-placement': dynamicAttr(() => { return this.getAttribute('data-tooltip-placement') || 'top'; })
            }
        }, () => { return this.tooltipTextNode; }));
    }
    connectedCallback() {
        super.connectedCallback();
        this.i18nUnsubscribe = addTranslationListener(() => {
            updateDynamicText(this);
        });
    }
    disconnectedCallback() {
        if (this.i18nUnsubscribe != null) {
            this.i18nUnsubscribe();
            this.i18nUnsubscribe = undefined;
        }
    }
}
